mapper.select:
SELECT  FROM suppression_entry
WHERE workspace_id = #{workspaceId}
ORDER BY created_at DESC, id DESC

SELECT channel, reason, MIN(created_at) AS since
FROM suppression_entry
WHERE workspace_id = #{workspaceId}
  AND (
    person_id = #{personId}

      OR

        (channel = #{ref.channel} AND address COLLATE utf8mb4_bin = #{ref.address})


  )
GROUP BY channel, reason
